package com.kagafei.g510supercheckoutphoto;
import android.app.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{
 static class P{String n;int p,i;P(String n,int p,int i){this.n=n;this.p=p;this.i=i;}} Map<String,P[]> m=new LinkedHashMap<>();Map<String,Integer> c=new LinkedHashMap<>();GridLayout g;TextView cv,tv;
 public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);g=findViewById(R.id.grid);cv=findViewById(R.id.cart);tv=findViewById(R.id.total);
 add("食品",new String[]{"食パン","牛乳","たまご","おにぎり","カレー","ヨーグルト"},new int[]{198,218,298,138,258,158},new int[]{R.drawable.bread,R.drawable.milk,R.drawable.eggs,R.drawable.onigiri,R.drawable.curry,R.drawable.yogurt});add("飲料",new String[]{"緑茶","水","コーヒー","オレンジジュース","コーラ","炭酸水"},new int[]{128,108,148,198,168,118},new int[]{R.drawable.green_tea,R.drawable.water,R.drawable.coffee,R.drawable.orange_juice,R.drawable.cola,R.drawable.sparkling_water});add("青果",new String[]{"りんご","バナナ","みかん","トマト","キャベツ","じゃがいも"},new int[]{158,198,398,258,198,298},new int[]{R.drawable.apple,R.drawable.banana,R.drawable.mandarin,R.drawable.tomato,R.drawable.cabbage,R.drawable.potato});add("日用品",new String[]{"ティッシュ","洗剤","歯ブラシ","ラップ","スポンジ","ごみ袋"},new int[]{398,348,198,258,128,298},new int[]{R.drawable.tissue,R.drawable.detergent,R.drawable.toothbrush,R.drawable.wrap,R.drawable.sponge,R.drawable.garbage_bag});add("精肉・鮮魚",new String[]{"牛肉","豚肉","鶏もも肉","生鮭","えび","ひき肉"},new int[]{680,480,398,580,498,458},new int[]{R.drawable.beef,R.drawable.pork,R.drawable.chicken,R.drawable.salmon,R.drawable.shrimp,R.drawable.minced_meat});add("惣菜",new String[]{"幕の内弁当","寿司盛合せ","唐揚げ","ポテトサラダ","サンドイッチ","プリン"},new int[]{598,798,398,258,328,198},new int[]{R.drawable.bento,R.drawable.sushi_pack,R.drawable.karaage,R.drawable.potato_salad,R.drawable.sandwich,R.drawable.pudding});
 LinearLayout tabs=findViewById(R.id.tabs);for(String k:m.keySet()){Button x=new Button(this);x.setText(k);x.setTextSize(16);x.setOnClickListener(v->show(k));tabs.addView(x,new LinearLayout.LayoutParams(170,-1));}findViewById(R.id.clear).setOnClickListener(v->{c.clear();refresh();});findViewById(R.id.pay).setOnClickListener(v->pay());show("食品");}
 void add(String k,String[] n,int[] p,int[] im){P[] a=new P[6];for(int j=0;j<6;j++)a[j]=new P(n[j],p[j],im[j]);m.put(k,a);}void show(String k){g.removeAllViews();for(P p:m.get(k)){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(5,5,5,5);card.setBackgroundColor(Color.WHITE);GridLayout.LayoutParams q=new GridLayout.LayoutParams();q.width=0;q.height=0;q.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);q.rowSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);q.setMargins(5,5,5,5);card.setLayoutParams(q);ImageView im=new ImageView(this);im.setImageResource(p.i);im.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(im,new LinearLayout.LayoutParams(-1,0,1f));Button bt=new Button(this);bt.setText(p.n+"　"+p.p+"円　＋");bt.setTextSize(15);bt.setOnClickListener(v->{c.put(p.n,c.getOrDefault(p.n,0)+1);refresh();});card.addView(bt,new LinearLayout.LayoutParams(-1,58));g.addView(card);}}void refresh(){int sum=0;StringBuilder s=new StringBuilder();for(String n:c.keySet())for(P[] a:m.values())for(P p:a)if(p.n.equals(n)){sum+=p.p*c.get(n);s.append(n).append(" × ").append(c.get(n)).append("\n");}cv.setText(c.isEmpty()?"商品はありません":s);tv.setText("合計 "+(sum+(int)(sum*.1))+"円");}void pay(){if(c.isEmpty())return;String[] x={"クレジットカード","電子マネー","QRコード","現金"};new AlertDialog.Builder(this).setTitle("お支払い方法").setItems(x,(d,w)->new AlertDialog.Builder(this).setTitle("会計完了").setMessage(x[w]+"でお支払いを受け付けました").setPositiveButton("完了",(a,z)->{c.clear();refresh();}).show()).show();}}
